// Storage layer keeps track of the highest fencing token it has accepted
function applyWrite(resourceId, fencingToken, payload) {
  const lastSeenToken = getLastToken(resourceId);
  if (fencingToken <= lastSeenToken) {
    throw new Error('stale fencing token, write rejected');
  }
  setLastToken(resourceId, fencingToken);
  persist(resourceId, payload);
}

