async function runNightlyReport(workerId) {
  const acquired = await redis.set(
    'lock:nightly-report:2026-07-08',
    workerId,
    'NX', 'EX', 120
  );

  if (!acquired) {
    console.log(workerId + ' did not get the lock, skipping');
    return;
  }

  try {
    await generateAndSendReport();
  } finally {
    await releaseLockIfOwner('lock:nightly-report:2026-07-08', workerId);
  }
}

